with b as (select version, content from operational_doc where version=(select max(version) from operational_doc)),
n as (select version, md5(content) bm, replace(content, 'every insert forces an `audit_log` row (version, md5, length).', 'every insert forces an `audit_log` row (version, md5, length, and since ASK 477 card, session and the prior version with its md5). The writer sets `SET LOCAL truth.card = ''<card label> <press time>Z <thread seat>''` in the same call as the insert; without it the row says card=NONE and the insert still succeeds. The card field is the writer''s claim, not proof of a press.') c, content from b)
select version, bm, md5(c) new_md5, length(c) new_len, (length(content)-length(replace(content,'every insert forces an `audit_log` row (version, md5, length).','')))/length('every insert forces an `audit_log` row (version, md5, length).') cnt from n;
